// Recurrence of any task ("toda tarefa pode ter recorrência", migration 0019): the task becomes the
// first occurrence of a recurring task of origin `task` — its client (an `include` link) or none
// (`internal`) — and the rest of the series is generated by the same engine as the registry's
// (generation.ts, marker included). Internal to the module: service.ts calls these inside its tenant
// transaction (createTask, updateTask, deleteTask, getTaskDetail).
//
// Rules:
// - permission: a member repeats a task that is theirs (responsible) or their department's, before and
//   after the change; anything else needs `registry`. The registry's recurring tasks (regimes, several
//   clients, groups) are never changed from a task (422);
// - the rule is stored as columns of the recurring task: start/end by date (the competences follow),
//   "a cada N", weekdays, "após N vezes" (its end date computed by the shared schedule);
// - a series edit takes the series' fields (title, client, category, responsible, department queue,
//   priority, description, time); the edited occurrence takes them at once, and the not-started ones from
//   the current competence on follow through `syncOpenOccurrences` (concluded and in-progress ones never
//   change). A client switch moves the not-started occurrences in place (internal included) instead of
//   canceling and regenerating them; a rule change moves the edited occurrence to the nearest new period
//   when it is free (the task the user is looking at does not become "canceled").

import { and, eq, ne, sql } from 'drizzle-orm';
import {
  addMonthKey,
  firstScheduledOccurrence,
  formatDateBR,
  monthKey,
  occurrencesInCompetence,
  seriesEndDate,
  type ISODate,
  type MonthKey,
  type RecurrenceFrequency,
  type RecurrenceNonBusinessDayRule,
  type ScheduledOccurrence,
  type TaskPriority,
  type TaskRecurrence,
  type taskRecurrenceInputSchema,
} from '@effinance/shared';
import type { z } from 'zod';
import { contacts, recurringTaskClients, recurringTasks, tasks, type TaskRow } from '../../db/schema';
import { ConflictError, ForbiddenError, NotFoundError, ValidationError } from '../../lib/errors';
import type { TaskContext } from './access';
import { encryptTaskText, RECURRING_DESCRIPTION } from './encrypted-text';
import {
  clientActiveIn,
  defaultWindow,
  deleteSeriesRows,
  ensureOccurrences,
  generationBounds,
  loadDefs,
  scheduleOf,
  workedOccurrenceCount,
  type GenClient,
  type GenDef,
} from './generation';
import { departmentOfMember, myName } from './shared';

export type TaskRecurrenceRule = z.output<typeof taskRecurrenceInputSchema>;

export const SERIES_FORBIDDEN_MESSAGE = 'Você só pode repetir tarefas suas ou do seu departamento.';
export const REGISTRY_SERIES_MESSAGE = 'Esta tarefa vem de uma tarefa recorrente do cadastro: altere-a em Recorrentes.';

/** What a series takes from its task (the description in clear text: encrypted here). */
export interface SeriesFields {
  title: string;
  description: string | null;
  clientId: string | null;
  categoryId: string | null;
  assigneeId: string | null;
  /** Already resolved (the responsible's department, else the queue). */
  departmentId: string | null;
  priority: TaskPriority;
  startTime: string | null;
  endTime: string | null;
}

/** The rule as stored in `recurring_tasks`. */
export interface SeriesRule {
  period: RecurrenceFrequency;
  dueDay: number;
  dueMonth: number | null;
  repeatInterval: number;
  weekdays: number[] | null;
  startDate: ISODate;
  endDate: ISODate | null;
  occurrenceLimit: number | null;
  targetDaysBefore: number;
  nonBusinessDayRule: RecurrenceNonBusinessDayRule;
  referenceOffset: number;
  startCompetence: MonthKey;
  endCompetence: MonthKey | null;
}

// ---------------------------------------------------------------------------
// Permission
// ---------------------------------------------------------------------------

/** Theirs (responsible) or their department's; anything with `registry`. */
export async function canManageSeries(
  ctx: TaskContext,
  state: { assigneeId: string | null; departmentId: string | null },
): Promise<boolean> {
  if (ctx.permissions.registry || state.assigneeId === ctx.userId) return true;
  if (!state.departmentId) return false;
  return (await departmentOfMember(ctx.db, ctx.workspaceId, ctx.userId)) === state.departmentId;
}

export async function assertCanManageSeries(ctx: TaskContext, state: { assigneeId: string | null; departmentId: string | null }): Promise<void> {
  if (!(await canManageSeries(ctx, state))) throw new ForbiddenError(SERIES_FORBIDDEN_MESSAGE);
}

// ---------------------------------------------------------------------------
// The rule
// ---------------------------------------------------------------------------

/** Earliest start of a new rule: the first day of the previous competence (a few days back is fine). */
function earliestStart(ctx: Pick<TaskContext, 'today'>): ISODate {
  return `${addMonthKey(monthKey(ctx.today), -1)}-01`;
}

/**
 * The stored rule from the input: defaults from the start (the task's due date, else today — or the
 * series' own start when editing), the end date of "após N vezes". A start moved further back than the
 * previous competence is refused (the generation would fill the past with overdue occurrences).
 */
export function seriesRule(ctx: Pick<TaskContext, 'today'>, input: TaskRecurrenceRule, fallbackStart: ISODate, previousStart: ISODate | null = null): SeriesRule {
  const startDate = input.startDate ?? previousStart ?? fallbackStart;
  if (startDate !== previousStart && startDate < earliestStart(ctx))
    throw new ValidationError(`A recorrência pode começar a partir de ${formatDateBR(earliestStart(ctx))}.`);
  const day = Number(startDate.slice(8, 10));
  const month = Number(startDate.slice(5, 7));
  const weekdays = input.frequency === 'weekly' ? input.weekdays : null;
  const rule: SeriesRule = {
    period: input.frequency,
    dueDay: input.frequency === 'daily' ? 1 : input.frequency === 'weekly' ? weekdays![0]! : (input.dueDay ?? day),
    dueMonth: input.dueMonth ?? (['bimonthly', 'quarterly', 'semiannual', 'annual'].includes(input.frequency) ? month : null),
    repeatInterval: input.interval,
    weekdays,
    startDate,
    endDate: input.ends === 'date' ? input.endDate : null,
    occurrenceLimit: input.ends === 'count' ? input.count : null,
    targetDaysBefore: input.targetDaysBefore,
    nonBusinessDayRule: input.nonBusinessDayRule,
    referenceOffset: input.referenceOffset,
    startCompetence: monthKey(startDate),
    endCompetence: null,
  };
  if (rule.endDate !== null && rule.endDate < startDate) throw new ValidationError('O término deve ser depois do início.');
  if (rule.occurrenceLimit !== null) {
    rule.endDate = seriesEndDate(scheduleOf(rule), rule.occurrenceLimit);
    if (rule.endDate === null) throw new ValidationError('Essa recorrência não tem tantas ocorrências.');
  }
  rule.endCompetence = rule.endDate ? monthKey(rule.endDate) : null;
  return rule;
}

/** The rule of a stored series (to keep it when only the fields change). */
export function storedRule(row: GenDef['row']): SeriesRule {
  return {
    period: row.period,
    dueDay: row.dueDay,
    dueMonth: row.dueMonth,
    repeatInterval: row.repeatInterval,
    weekdays: row.weekdays,
    startDate: row.startDate!,
    endDate: row.endDate,
    occurrenceLimit: row.occurrenceLimit,
    targetDaysBefore: row.targetDaysBefore,
    nonBusinessDayRule: row.nonBusinessDayRule,
    referenceOffset: row.referenceOffset,
    startCompetence: row.startCompetence,
    endCompetence: row.endCompetence,
  };
}

/** The first occurrence of a rule (422 when it has none). */
export function firstOccurrenceOf(rule: SeriesRule): ScheduledOccurrence {
  const first = firstScheduledOccurrence(scheduleOf(rule));
  if (!first) throw new ValidationError('Essa recorrência não tem nenhuma ocorrência.');
  return first;
}

/** Nominal date of an occurrence of the series (its period under the current rule; else its due date). */
function nominalOf(rule: SeriesRule, row: Pick<TaskRow, 'periodKey' | 'competence' | 'dueDate'>): ISODate {
  const found = occurrencesInCompetence(scheduleOf(rule), row.competence!).find((o) => o.periodKey === row.periodKey);
  return found?.nominalDate ?? (row.periodKey!.length === 10 ? row.periodKey! : row.dueDate!);
}

/** The rule ending at this occurrence (`recurrence: null`): nothing after its nominal date. */
export function endedAt(rule: SeriesRule, row: Pick<TaskRow, 'periodKey' | 'competence' | 'dueDate'>): SeriesRule {
  const endDate = nominalOf(rule, row);
  return { ...rule, endDate: endDate < rule.startDate ? rule.startDate : endDate, occurrenceLimit: null, endCompetence: monthKey(endDate < rule.startDate ? rule.startDate : endDate) };
}

/** A client of the office in the competence (contract started, not inactivated before it began). */
export async function assertClientActiveIn(ctx: Pick<TaskContext, 'db' | 'workspaceId'>, clientId: string | null, competence: MonthKey): Promise<void> {
  if (!clientId) return;
  const [client] = await ctx.db
    .select({
      id: contacts.id,
      name: contacts.name,
      tradeName: contacts.tradeName,
      taxRegime: contacts.taxRegime,
      status: contacts.status,
      contractStartDate: contacts.contractStartDate,
      inactivatedAt: contacts.inactivatedAt,
    })
    .from(contacts)
    .where(and(eq(contacts.workspaceId, ctx.workspaceId), eq(contacts.kind, 'client'), eq(contacts.id, clientId)));
  if (!client) throw new NotFoundError('Cliente não encontrado');
  if (!clientActiveIn(client as GenClient, competence))
    throw new ValidationError(`O cliente ${client.status === 'inactive' ? 'não está ativo' : 'ainda não está ativo'} em ${competence.slice(5, 7)}/${competence.slice(0, 4)}.`);
}

// ---------------------------------------------------------------------------
// The series
// ---------------------------------------------------------------------------

/** A task's recurrence (origin `task`). */
export async function loadTaskSeries(ctx: Pick<TaskContext, 'db' | 'workspaceId'>, id: string): Promise<GenDef> {
  const [def] = await loadDefs(ctx, [id], { origin: 'task' });
  if (!def) throw new NotFoundError('Recorrência não encontrada');
  return def;
}

async function seriesValues(ctx: TaskContext, fields: SeriesFields, rule: SeriesRule) {
  return {
    name: fields.title,
    description: await encryptTaskText(ctx.cipher, RECURRING_DESCRIPTION, fields.description),
    departmentId: fields.departmentId,
    categoryId: fields.categoryId,
    defaultAssigneeId: fields.assigneeId,
    priority: fields.priority,
    startTime: fields.startTime,
    endTime: fields.endTime,
    internal: fields.clientId === null,
    ...rule,
  };
}

async function replaceClient(ctx: TaskContext, id: string, clientId: string | null) {
  await ctx.db
    .delete(recurringTaskClients)
    .where(and(eq(recurringTaskClients.workspaceId, ctx.workspaceId), eq(recurringTaskClients.recurringTaskId, id)));
  if (clientId)
    await ctx.db.insert(recurringTaskClients).values({ workspaceId: ctx.workspaceId, recurringTaskId: id, clientId, mode: 'include' });
}

/** Inserts the series (origin `task`) with its client link; the caller writes the first occurrence. */
export async function insertSeries(ctx: TaskContext, fields: SeriesFields, rule: SeriesRule): Promise<string> {
  const [row] = await ctx.db
    .insert(recurringTasks)
    .values({
      workspaceId: ctx.workspaceId,
      ...(await seriesValues(ctx, fields, rule)),
      origin: 'task',
      regimes: [],
      createdBy: ctx.userId,
      createdByName: myName(ctx),
    })
    .returning({ id: recurringTasks.id });
  await replaceClient(ctx, row!.id, fields.clientId);
  return row!.id;
}

export async function updateSeries(ctx: TaskContext, id: string, fields: SeriesFields, rule: SeriesRule): Promise<void> {
  await ctx.db
    .update(recurringTasks)
    .set(await seriesValues(ctx, fields, rule))
    .where(and(eq(recurringTasks.workspaceId, ctx.workspaceId), eq(recurringTasks.id, id), eq(recurringTasks.origin, 'task')));
  await replaceClient(ctx, id, fields.clientId);
}

/** Occurrence columns of a task of the series in a period. */
export function occurrenceColumns(seriesId: string, scheduled: ScheduledOccurrence, assigneeId: string | null) {
  return {
    recurringTaskId: seriesId,
    occurrenceOrigin: 'task' as const,
    competence: scheduled.competence,
    periodKey: scheduled.periodKey,
    referenceMonth: scheduled.referenceMonth,
    dueDate: scheduled.legalDueDate,
    targetDate: scheduled.targetDate,
    startDate: null,
    assigneeSource: assigneeId ? ('default' as const) : null,
  };
}

/** Generates the default window of the series (the first occurrence already exists). */
export async function generateSeries(ctx: TaskContext, id: string): Promise<void> {
  await ensureOccurrences(ctx, defaultWindow(ctx.today), { recurringTaskIds: [id] });
}

/**
 * A client switch (internal included): the not-started occurrences from the current competence on — and
 * the edited one, whatever its state — change client in place, unless that period already has an
 * occurrence for the new client (then the sync cancels the old one and keeps that).
 */
export async function moveSeriesClient(ctx: TaskContext, seriesId: string, editedId: string, clientId: string | null): Promise<void> {
  const { current } = generationBounds(ctx.today);
  const target = clientId === null ? sql`n.client_id is null` : sql`n.client_id = ${clientId}`;
  await ctx.db
    .update(tasks)
    .set({ clientId })
    .where(
      and(
        eq(tasks.workspaceId, ctx.workspaceId),
        eq(tasks.recurringTaskId, seriesId),
        sql`(${tasks.id} = ${editedId} or (${tasks.status} = 'todo' and ${tasks.competence} >= ${current}))`,
        // Outer columns spelled out (pitfall #11).
        sql`not exists (select 1 from tasks n where n.workspace_id = tasks.workspace_id and n.recurring_task_id = tasks.recurring_task_id and n.period_key = tasks.period_key and ${target})`,
      ),
    );
}

/**
 * After a rule change: a not-started occurrence whose period no longer exists moves to the nearest new
 * period on or after its due date (up to 3 competences ahead), when no occurrence of the series has it.
 */
export async function rekeyOccurrence(ctx: TaskContext, row: TaskRow, rule: SeriesRule): Promise<void> {
  if (row.status !== 'todo' || !row.competence || !row.periodKey || !row.dueDate) return;
  const schedule = scheduleOf(rule);
  if (occurrencesInCompetence(schedule, row.competence).some((o) => o.periodKey === row.periodKey)) return;
  const candidates = [0, 1, 2, 3]
    .flatMap((n) => occurrencesInCompetence(schedule, addMonthKey(row.competence!, n)))
    .filter((o) => o.nominalDate >= row.dueDate!);
  const next = candidates[0];
  if (!next) return;
  const [taken] = await ctx.db
    .select({ id: tasks.id })
    .from(tasks)
    .where(and(eq(tasks.workspaceId, ctx.workspaceId), eq(tasks.recurringTaskId, row.recurringTaskId!), eq(tasks.periodKey, next.periodKey), ne(tasks.id, row.id)))
    .limit(1);
  if (taken) return;
  await ctx.db
    .update(tasks)
    .set({
      competence: next.competence,
      periodKey: next.periodKey,
      referenceMonth: next.referenceMonth,
      dueDate: next.legalDueDate,
      targetDate: next.targetDate,
    })
    .where(and(eq(tasks.workspaceId, ctx.workspaceId), eq(tasks.id, row.id)));
}

/**
 * Deleting a task of a series (`deleteTasks`): the whole series goes while nobody worked on any of its
 * occurrences (the generation would bring a single one back); otherwise 409.
 */
export async function deleteTaskSeries(ctx: TaskContext, seriesId: string): Promise<void> {
  const n = await workedOccurrenceCount(ctx, seriesId);
  if (n > 0)
    throw new ConflictError(
      `Esta tarefa se repete e já tem histórico (${n} ${n === 1 ? 'ocorrência trabalhada' : 'ocorrências trabalhadas'}). Cancele esta ocorrência ou encerre a recorrência.`,
      { occurrences: n },
    );
  await deleteSeriesRows(ctx, seriesId);
}

/** The rule as `TaskDetail.recurrence` shows it. */
export async function toTaskRecurrence(ctx: TaskContext, def: GenDef): Promise<TaskRecurrence> {
  const row = def.row;
  const schedule = scheduleOf(row);
  const upcoming: TaskRecurrence['upcoming'] = [];
  for (let m = monthKey(ctx.today), guard = 0; upcoming.length < 5 && guard < 24; m = addMonthKey(m, 1), guard++) {
    if (row.endCompetence && m > row.endCompetence) break;
    for (const o of occurrencesInCompetence(schedule, m)) {
      if (o.legalDueDate >= ctx.today && upcoming.length < 5)
        upcoming.push({ periodKey: o.periodKey, legalDueDate: o.legalDueDate, targetDate: o.targetDate });
    }
  }
  const [count] = await ctx.db
    .select({ n: sql<number>`count(*)`.mapWith(Number) })
    .from(tasks)
    .where(and(eq(tasks.workspaceId, ctx.workspaceId), eq(tasks.recurringTaskId, row.id)));
  const anchored = ['bimonthly', 'quarterly', 'semiannual', 'annual'].includes(row.period);
  return {
    recurringTaskId: row.id,
    frequency: row.period,
    interval: row.repeatInterval,
    weekdays: row.weekdays ?? [],
    dueDay: row.period === 'daily' || row.period === 'weekly' ? null : row.dueDay,
    dueMonth: anchored ? row.dueMonth : null,
    startDate: row.startDate!,
    ends: row.occurrenceLimit !== null ? 'count' : row.endDate !== null ? 'date' : 'never',
    endDate: row.endDate,
    count: row.occurrenceLimit,
    targetDaysBefore: row.targetDaysBefore,
    nonBusinessDayRule: row.nonBusinessDayRule,
    referenceOffset: row.referenceOffset,
    active: upcoming.length > 0,
    upcoming,
    occurrenceCount: count?.n ?? 0,
    canEdit: await canManageSeries(ctx, { assigneeId: row.defaultAssigneeId, departmentId: row.departmentId }),
  };
}
